-- DYNAMIC-WORKERS-COST-1 (2026-11-05, charter pillar cost; owner target USD 200-300 a month, measured, not estimated; found while checking roadmap row 1694): a cost line the ledger had no price for.
-- WHAT WAS READ (2026-11-05, GET /accounts/{id}/billable-usage?from=2026-10-07&to=2026-11-05 with the repository token, 267 lines): the report is readable with that token (HTTP 200; the worker tokens get 403,
-- which is what docs/COST-LEDGER-ALLVENDOR.md recorded). It carries Workers / "Dynamic Workers (First 1,000 are included)", priced USD 0.002 per unique Dynamic Worker per day: 276 on 2026-10-31, 1,408
-- on 11-01, 2,440 on 11-02, 2,043 on 11-03, 2,098 on 11-04 (USD 0.55, 2.82, 4.88, 4.09, 4.20; USD 16.61 in the window), against about 250 a day before 11-01; 85 so far on 11-05. At 2,000 a day that is
-- about USD 120 a month, 40 percent of the USD 300 budget, and the ledger showed none of it (no price-book row, no dataset). The same report agrees with the fleet's own Workers AI line
-- within 0.3 percent (Workers AI 2026-11-02: report 40.447, cost_daily 40.34; 11-03: 39.138 and 39.03).
-- WHAT THIS DOES: the price (cost_price_book), the doer for the cause (the dataset workersInvocationsByOwnerAndScriptGroups.uniq.distinctDynamicWorkerCount returns the same counts to the unit but has no script
-- dimension, so it prices the line and cannot name the caller; qnfo-infra 1.14.0 reads it), and the issue below.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM cost_price_book WHERE vendor = 'cloudflare' AND product = 'workers' AND metric = 'dynamic_workers'; DELETE FROM cost_usage_daily WHERE vendor = 'cloudflare' AND product = 'workers' AND metric = 'dynamic_workers'; DELETE FROM cost_vendor_month WHERE vendor = 'cloudflare' AND product = 'workers' AND metric = 'dynamic_workers'; UPDATE roadmap_implementation SET evidence = (SELECT b.evidence FROM bak_20261105_dynamic_workers b WHERE b.id = roadmap_implementation.id) WHERE id IN (SELECT id FROM bak_20261105_dynamic_workers)
-- BACKUP: cost_price_book

CREATE TABLE IF NOT EXISTS bak_20261105_dynamic_workers AS SELECT * FROM roadmap_implementation WHERE id = 1694;

INSERT OR IGNORE INTO cost_price_book (vendor, product, metric, kind, unit, included_per_month, usd_per_block, block_size, source_url, checked_on, note) VALUES
  ('cloudflare', 'workers', 'dynamic_workers', 'flow', 'workers', 1000, 0.002, 1, 'https://developers.cloudflare.com/dynamic-workers/pricing/', '2026-11-05', 'Dynamic Workers: first 1,000 unique workers a month included, USD 0.002 per additional unique Dynamic Worker per day (the billing report prices ContractedCost = count x 0.002 once the cumulated count passes 1,000); every LOADER.load without a stable id is a new unique worker');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'DYNAMIC-WORKERS-COST-1: about 2,000 unique Dynamic Workers a day since 2026-11-01 cost USD 4 to 5 a day and no caller is named',
 'Charter pillar: cost. Doer: the code loop (qnfo-code-orchestrator first). Measured 2026-11-05 from the billing report (GET /billable-usage, repository token) and the GraphQL dataset workersInvocationsByOwnerAndScriptGroups.uniq.distinctDynamicWorkerCount (identical counts): 276 on 10-31, 1,408 on 11-01, 2,440 on 11-02, 2,043 on 11-03, 2,098 on 11-04, 85 so far on 11-05; USD 0.002 each after the first 1,000 a month, so USD 4 to 5 a day, about USD 120 a month at that pace, 40 percent of the USD 300 budget (cost_price_book row added by migrations/2026-11-05-dynamic-workers-cost.sql, qnfo-infra 1.14.0 reads the count hourly into cost_vendor_month product workers metric dynamic_workers). The dataset has no script dimension, so the caller is not named. Suspects, from the sources: every env.LOADER.load(...) with inline modules and no stable id is a new unique worker: qnfo-code-orchestrator dynamicStart (JS_VERIFY = auto in wrangler.toml: one load per JS patch verification, syntax only) and cbExec (the weekly coding battery, 52 pairs on 2026-11-05), qnfo-ops run_code (two sites), qnfo-ai run_code, and qnfo-agents (its worker_loaders binding serves the computer runtime, backend worker-javascript). Step 1 (attribution, one change per call site): count each LOADER.load by caller in qnfo-audit (cost_usage_daily vendor loader, product the worker name, metric dynamic_worker_loads, a small helper that increments it best effort; no code text is stored) so the next day names the caller. Step 2 (the cut, once named): load by a stable id (env.LOADER.get(sha256 of the source, callback)) so an identical source reuses one worker, and where the load only proves syntax (dynamicStart) replace it by an in-process check or the publisher''s node --check (agent_issues 2008) so it costs nothing. Done: the daily dynamic_workers count (cost_usage_daily vendor cloudflare product workers) averages 300 or fewer over three complete days, and the callers of the earlier 2,000 a day are named on this issue with their counts. Failure mode: a stable id that hashes the whole source dedupes only identical code; if the callers produce distinct code each time, the cut is the syntax-only replacement, not the id.' || char(10) ||
 'code-task: repo=qnfo-workers path=qnfo-code-orchestrator/worker.js' || char(10) ||
 'code-anchor: async function dynamicStart(env, src) {',
 'session', 'reliability', 'high', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'DYNAMIC-WORKERS-COST-1:%' AND status = 'open');

UPDATE remediation_contracts
SET verify_probe = 'SELECT ''1'' AS expected, CASE WHEN (SELECT COUNT(*) FROM cost_usage_daily WHERE vendor = ''cloudflare'' AND product = ''workers'' AND metric = ''dynamic_workers'' AND date >= date(''now'', ''-3 days'') AND date < date(''now'')) < 3 THEN ''0: fewer than 3 complete days of the dynamic_workers meter'' WHEN (SELECT AVG(quantity) FROM cost_usage_daily WHERE vendor = ''cloudflare'' AND product = ''workers'' AND metric = ''dynamic_workers'' AND date >= date(''now'', ''-3 days'') AND date < date(''now'')) <= 300 THEN ''1'' ELSE ''0: average of the last 3 complete days is above 300'' END AS observed',
    verify_transport = 'd1-query', status = 'active', attempts = 0, last_verdict = NULL, next_due_at = datetime('now'), expected_cadence_h = 24, module = 'dynamic-workers-cost',
    precondition = 'DYNAMIC-WORKERS-COST-1: about 2,000 unique Dynamic Workers a day since 2026-11-01 and no caller named',
    action = 'the code loop attributes each LOADER.load by caller, then loads by a stable id or removes the syntax-only load; the daily count is the evidence'
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title LIKE 'DYNAMIC-WORKERS-COST-1:%' AND status = 'open' ORDER BY id DESC LIMIT 1);

UPDATE roadmap_implementation
SET evidence = evidence || ' | W2-C 2026-11-05 correction: the billing report (GET /billable-usage) is readable with the repository token (HTTP 200, 267 lines for 2026-10-07 to 11-05, no AI Search line yet); only the worker tokens get 403. The report lists a charge only above the allowances, so the meters stay the way to see AI Search usage inside them. Reading it also showed a line the ledger lacked, Dynamic Workers (about USD 120 a month at 2,000 a day; DYNAMIC-WORKERS-COST-1).'
WHERE id = 1694 AND item = 'RM-AISEARCH-GA-MIGRATE-1' AND evidence NOT LIKE '%W2-C 2026-11-05 correction%';

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'COST-INVOICE-LINES-1: read the billing report (readable with the repository token) beside the meters, so every cost line has an invoice check',
 'Charter pillar: cost. Doer: the code loop (scripts/cost_ledger.py). Measured 2026-11-05: GET /accounts/{id}/billable-usage?from=&to= answers 200 with the repository token in the GitHub runner (the Workers'' tokens get 403, which is what docs/COST-LEDGER-ALLVENDOR.md recorded); 267 lines for 2026-10-07 to 11-05 with ServiceFamilyName, ServiceName, ChargePeriodStart, ConsumedQuantity, PricingQuantity, ContractedCost and CumulatedPricingQuantity. It matches the fleet Workers AI line within 0.3 percent (2026-11-02: report 40.447, cost_daily 40.34) and showed a line the meters had no price for (Dynamic Workers, DYNAMIC-WORKERS-COST-1). Every cost_vendor_month line is a meter times a published price; the report is the only invoice-grade check and nothing reads it except the AI Search snapshot. Change: in scripts/cost_ledger.py (hourly consume heavy job, the runner has the token) write one row per day and service of the report into a new table cost_invoice_daily (date, family, service, usd, quantity, unit, observed_at; DDL by a migration) and a view v_cost_meter_vs_invoice that sets each cost_vendor_month product-month beside the invoice sum of its services (Workers AI against cost_daily workers_ai, Dynamic Workers, R2, Vectorize, KV, D1, Durable Objects, Containers, Queues, Workers CPU and requests, Email, AI Search). Do NOT add the invoice rows to v_cost_lines_month or cost_vendor_month: the same product would be counted twice; the view compares, the ledger line keeps the meter until the comparison has run for 7 days and the owner-visible total can switch a product to invoice evidence on a measured agreement. Register a metric cost_invoice_vs_meter_gap_pct (largest absolute gap over products above USD 1 a month) with its trigger at 15 percent or name the exemption in the same migration, and map its breach cause (METRIC-CAUSE-AT-REGISTRATION-1). Failure mode: the report lists a charge only above the allowances and lags the day by hours, so a product inside its allowance has invoice 0 and a meter above 0; compare only products where the invoice sum is above 0 or the meter gross is above USD 1. Done: cost_invoice_daily has rows for the last 30 days, v_cost_meter_vs_invoice lists every product with both numbers, and the gap metric is measured.' || char(10) ||
 'code-task: repo=qnfo-workers path=scripts/cost_ledger.py' || char(10) ||
 'code-anchor: def ai_search_summary(d1, day, call=cf):',
 'session', 'reliability', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'COST-INVOICE-LINES-1:%' AND status = 'open');

UPDATE remediation_contracts
SET verify_probe = 'SELECT ''1'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM sqlite_master WHERE name = ''cost_invoice_daily'') AND (SELECT COUNT(*) FROM cost_invoice_daily WHERE date >= date(''now'', ''-3 days'')) > 0 AND EXISTS (SELECT 1 FROM sqlite_master WHERE name = ''v_cost_meter_vs_invoice'') THEN ''1'' ELSE ''0: cost_invoice_daily or v_cost_meter_vs_invoice missing, or no row in the last 3 days'' END AS observed',
    verify_transport = 'd1-query', status = 'active', attempts = 0, last_verdict = NULL, next_due_at = datetime('now'), expected_cadence_h = 24, module = 'cost-invoice-lines',
    precondition = 'COST-INVOICE-LINES-1: the billing report is readable with the repository token and nothing reads it into the ledger',
    action = 'the code loop writes the report into cost_invoice_daily and a meter-versus-invoice view; the rows are the evidence'
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title LIKE 'COST-INVOICE-LINES-1:%' AND status = 'open' ORDER BY id DESC LIMIT 1);
